screen = turtle.Screen()
screen.setup(int(1232*SCALE)+60, int(1164*SCALE)+60)
screen.title("Medallion")
screen.bgcolor(PAPER)
screen.tracer(0)
t = turtle.Turtle(visible=False)
t.speed(110)
t.pensize(5)
count = 0

def tick():
    global count
    count += 1
    if count % STEP == 0:
        screen.update(); time.sleep(DELAY)

def gray(lo, hi):
    g = random.randint(lo, hi)
    return "#%02x%02x%02x" % (g, g, min(255, g + 4))

def resample(pts, gap=5.0):
    out = [pts[0]]
    for (x1, y1), (x2, y2) in zip(pts, pts[1:]):
        d = math.hypot(x2-x1, y2-y1)
        n = max(1, int(d // gap))
        for i in range(1, n + 1):
            f = i / n
            out.append((x1 + (x2-x1)*f, y1 + (y2-y1)*f))
    return out

def wobble(pts, big, small):
    dx = dy = 0.0
    res = []
    for x, y in pts:
        dx = dx*0.92 + random.uniform(-big, big)
        dy = dy*0.92 + random.uniform(-big, big)
        res.append((x + dx + random.uniform(-small, small),
                    y + dy + random.uniform(-small, small)))
    return res

def extend(pts, amt):
    (x0, y0), (x1, y1) = pts[0], pts[1]
    d = math.hypot(x1-x0, y1-y0) or 1
    a = (x0 - (x1-x0)/d*amt, y0 - (y1-y0)/d*amt)
    (x0, y0), (x1, y1) = pts[-1], pts[-2]
    d = math.hypot(x1-x0, y1-y0) or 1
    b = (x0 - (x1-x0)/d*amt, y0 - (y1-y0)/d*amt)
    return [a] + pts + [b]

def stroke_path(path, big, small, lo, hi, widths, overshoot):
    pts = resample([(x*SCALE, y*SCALE) for x, y in path], 5.0)
    if len(pts) < 2:
        return
    closed = math.dist(pts[0], pts[-1]) < 3
    if not closed and overshoot:
        pts = extend(pts, random.uniform(0, overshoot))
    if random.random() < 0.5:
        pts.reverse()
    pts = wobble(pts, big, small)
    i = 0
    t.penup(); t.goto(pts[0]); t.pendown()
    while i < len(pts) - 1:
        t.pencolor(gray(lo, hi))
        t.pensize(random.choice(widths))
        for p in pts[i+1:i+9]:
            t.goto(p); tick()
        i += 8
    t.penup()

def full_pass(big, small, lo, hi, widths, overshoot):
    order = PATHS[:]
    random.shuffle(order)
    for p in order:
        stroke_path(p, big, small, lo, hi, widths, overshoot)

